/** Chọn người kế tiếp trong danh sách — luật phân công đơn giản, vẫn thuộc tầng nghiệp vụ. */
function nextAssignee(current: string | null | undefined): string {
  const i = current ? ROSTER.indexOf(current) : -1;
  return ROSTER[(i + 1) % ROSTER.length] ?? ROSTER[0] ?? '';
}

/**
 * Suy trạng thái của MỘT nhóm từ danh sách việc của nó.
 * Thứ tự ưu tiên: bị chặn (error) → xong hết (complete) → đã động vào (partial) → chưa gì (empty).
 * `vnr-form-section-nav` KHÔNG tự chấm trạng thái — nó chỉ vẽ cái ta tính ở đây.
 */
function groupState(tasks: readonly VnrChecklistTask[]): VnrFormNavState {
  if (tasks.length === 0) return 'empty';
  if (tasks.some((t) => t.status === 'blocked')) return 'error';
  if (tasks.every((t) => t.status === 'done')) return 'complete';
  if (tasks.some((t) => t.status === 'done' || t.status === 'doing')) return 'partial';
  return 'empty';
}

/** Mức hoàn thiện dạng "x/y" hiện cạnh tên nhóm. */
function groupMeta(tasks: readonly VnrChecklistTask[]): string {
  return `${tasks.filter((t) => t.status === 'done').length}/${tasks.length}`;
}

/** Quy đổi lộ trình sang cấu hình điều hướng — đầu vào duy nhất của vnr-form-section-nav. */
function toNavSections(groups: readonly OnboardGroup[]): VnrFormNavSection[] {
  return groups.map((g) => ({
    id: g.id,
    label: g.label,
    state: groupState(g.tasks),
    meta: groupMeta(g.tasks),
  }));
}

/** Tổng hợp tiến độ toàn quy trình — dữ liệu cho header và thẻ tóm tắt cột trái. */
interface OnboardProgress {
  readonly total: number;
  readonly done: number;
  readonly doing: number;
  readonly blocked: number;
  readonly percent: number;
  readonly requiredLeft: number;
}

function summarize(groups: readonly OnboardGroup[]): OnboardProgress {
  const all = groups.flatMap((g) => g.tasks);
  const done = all.filter((t) => t.status === 'done').length;
  return {
    total: all.length,
    done,
    doing: all.filter((t) => t.status === 'doing').length,
    blocked: all.filter((t) => t.status === 'blocked').length,
    percent: all.length === 0 ? 0 : Math.round((done / all.length) * 100),
    requiredLeft: all.filter((t) => t.required && t.status !== 'done').length,
  };
}

/** Đảo trạng thái một việc: chưa làm ↔ hoàn thành. Việc đang bị chặn thì giữ nguyên. */
function flipStatus(s: VnrChecklistStatus): VnrChecklistStatus {
  if (s === 'blocked') return s;
  return s === 'done' ? 'todo' : 'done';
}

/** Áp một phép biến đổi lên đúng nhóm, trả về lộ trình MỚI (bất biến ⇒ signal bắn thay đổi). */
function patchGroup(
  groups: readonly OnboardGroup[],
  groupId: string,
  fn: (tasks: readonly VnrChecklistTask[]) => readonly VnrChecklistTask[],
): OnboardGroup[] {
  return groups.map((g) => (g.id === groupId ? { ...g, tasks: fn(g.tasks) } : g));
}

